            return any(_match_segments(alt.split("/"), rel) for alt in self.alternatives)
        return any(_glob(alt, rel[-1]) for alt in self.alternatives)


def _parse(text, base):
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
