        if anchored:
            line = line.lstrip("/")
        if not line:
            continue
        rules.append(_Rule(base, negated, dir_only, anchored, _expand_braces(line)))
    return rules


def _decide(rules, parts, is_dir, excluded):
    for rule in reversed(rules):
        if rule.matches(parts, is_dir):
            return not rule.negated
    return excluded


def _builtin_excluded(path, mode):
    if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        return True
    with open(path, "rb") as f:
        return _GENERATED_MARKER in f.readline()


def _walk(node, parts, rules, excluded, out):
    if not excluded:
        entry = node.files.get(_fold(_IGNORE_FILE))
        if entry is not None and entry[0] == _IGNORE_FILE:
            with open(entry[1], "rb") as f:
                text = f.read().decode("utf-8")
            rules = rules + _parse(text, parts)
    for name, path, mode in node.files.values():
        file_parts = parts + [name]
        state = _decide(rules, file_parts, False, _builtin_excluded(path, mode))
        if state:
