class _Rule:
    def __init__(self, base, negated, dir_only, anchored, alternatives):
        self.base = base  # path parts of the directory holding the .packignore
        self.negated = negated
        self.dir_only = dir_only
        self.anchored = anchored
        self.alternatives = alternatives

    def matches(self, parts, is_dir):
        if self.dir_only and not is_dir:
            return False
        base = self.base
        if len(parts) <= len(base) or parts[:len(base)] != base:
            return False
        rel = parts[len(base):]
        if self.anchored:
            return any(_match_segments(alt.split("/"), rel) for alt in self.alternatives)
        return any(_glob(alt, rel[-1]) for alt in self.alternatives)


def _parse(text, base):
    rules = []
    for line in text.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        negated = line.startswith("!")
        if negated:
            line = line[1:]
        dir_only = line.endswith("/")
        line = line.rstrip("/")
        anchored = "/" in line
        if anchored:
            line = line.lstrip("/")
        if not line:
            continue
        rules.append(_Rule(base, negated, dir_only, anchored, _expand_braces(line)))
    return rules


def _decide(rules, parts, is_dir, excluded):
    for rule in reversed(rules):
        if rule.matches(parts, is_dir):
            return not rule.negated
    return excluded


def _builtin_excluded(path, mode):
    if mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH):
        return True
    with open(path, "rb") as f:
        return _GENERATED_MARKER in f.readline()


def _walk(node, parts, rules, excluded, out):
    if not excluded:
        key = _fold(_IGNORE_FILE)
        if key in node.dirs and node.dirs[key][0] == _IGNORE_FILE:
            raise PackignoreError(f"{_IGNORE_FILE} is a directory: {'/'.join(parts + [_IGNORE_FILE])}")
        entry = node.files.get(key)
        if entry is not None and entry[0] == _IGNORE_FILE:
            with open(entry[1], "rb") as f:
                data = f.read()
            try:
                text = data.decode("utf-8")
            except UnicodeDecodeError as e:
                raise PackignoreError(f"{entry[1]}: not valid UTF-8 ({e})") from None
            rules = rules + _parse(text, parts)
    for name, path, mode in node.files.values():
        file_parts = parts + [name]
        if _decide(rules, file_parts, False, excluded or _builtin_excluded(path, mode)):
            out.append("/".join(file_parts))
    for name, child in node.dirs.values():
        dir_parts = parts + [name]
        _walk(child, dir_parts, rules, _decide(rules, dir_parts, True, excluded), out)


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    out = []
    _walk(_scan(root), [], [], False, out)
    return sorted(out)

