cat > /tmp/pk/fuzz3.py <<'EOF'
import os, sys, random, subprocess, tempfile, shutil
sys.path.insert(0, "/work/repo")
from snapshot.ignore import ignored_files
seed0 = int(sys.argv[1]); N = int(sys.argv[2])
NM = ["a","b","ab","ba","A"]
def rpat(r):
    segs = []
    for _ in range(r.choice([1,1,1,2,2,3])):
        segs.append(r.choice(NM + ["*","**","?","a*","*b","?b","{a,b}","{ab,b}*","{,a}b","a?"]))
    p = "/".join(segs)
    if r.random()<0.25: p = "/"+p
    if r.random()<0.25: p += "/"
    if r.random()<0.5: p = "!"+p
    return p
def gen(r):
    d = tempfile.mkdtemp(prefix="fz3")
    dirs = [""]
    for _ in range(r.randint(1,6)):
        dirs.append(os.path.join(r.choice(dirs), r.choice(NM[:4])))
    for dd in set(dirs):
        os.makedirs(os.path.join(d,dd), exist_ok=True)
        for n in r.sample(NM[:4], r.randint(1,3)):
            f = os.path.join(d,dd,n)
            if not os.path.isdir(f):
                open(f,"w").write(r.choice(["", "", "@generated"]))
                if r.random()<0.15: os.chmod(f, 0o755)
        if r.random()<0.7:
            open(os.path.join(d,dd,".packignore"),"w").write("\n".join(rpat(r) for _ in range(r.randint(1,6))))
    return d
bad = 0
for i in range(N):
    seed = seed0*100000+i
    d = gen(random.Random(seed))
    p = subprocess.run([sys.executable,"/work/repo/tools/packignore",d],capture_output=True,text=True)
    if p.returncode:
        if "timed out" not in p.stderr: print("ERR", seed, p.stderr)
        shutil.rmtree(d); continue
    exp = sorted(p.stdout.splitlines())
    try: got = ignored_files(d)
    except Exception as e: got = ("ERR", e)
    if exp != got:
        bad += 1
        print("SEED", seed)
        for dp,dn,fn in os.walk(d):
            for n in fn:
                f=os.path.join(dp,n); print("   ", os.path.relpath(f,d), oct(os.stat(f).st_mode&0o777), repr(open(f).read()))
        print("  exp", exp); print("  got", got)
        if bad > 2: break
    shutil.rmtree(d)
print("done", N, "bad", bad)
EOF
